public List<String> filterData(List<String> data) {
    if (data == null || data.isEmpty()) {
        return Collections.emptyList();
    }
    List<String> filteredData = new ArrayList<>();
    for (String d : data) {
        if (!d.isEmpty()) {
            filteredData.add(d);
        }
    }
    return filteredData;
}
